//@ category="Analysis"

import ghidra.app.decompiler.DecompInterface;
import ghidra.util.task.ConsoleTaskMonitor;

/**
 * Headless decompilation script: exports all functions' C pseudocode to a file.
 * Usage with analyzeHeadless:
 *   analyzeHeadless <project> <binary> -scriptPath /scripts -postScript DecompileAll.java "/out/akira.c"
 */
public class DecompileAll extends ghidra.app.plugin.core.decompile.DecompilerPlugin {

	private DecompInterface decomp;

	@Override
	public void run(String[] args) throws Exception {
		String outputPath = (args.length > 0) ? args[0] : null;

		decomp = new DecompInterface();
		decomp.openProgram(getCurrentProgram());

		StringBuilder sb = new StringBuilder();
		int fnCount = 0;

		for (ghidra.program.model.listing.Function fn :
			 getCurrentProgram().getFunctionManager().getFunctions(true)) {
			DecompResult result = decomp.decompileFunction(fn, 120, getMonitor());
			if (result != null && result.decompileCompleted()) {
				sb.append(result.getDecompiledFunction().getC()).append("\n\n");
				fnCount++;
			}
		}

		String output = sb.toString();

		if (outputPath != null) {
			print("Writing decompiled output to: " + outputPath);
			FileIO.writeFile(new File(outputPath), output.getBytes());
		}
		else {
			getTool().show(this, "Decompiled Functions", output);
		}

		print("Decomplied " + fnCount + " function(s).");
	}
}

