import ghidra.app.script.GhidraScript;
import ghidra.app.decompiler.*;
import ghidra.program.model.listing.Function;
import java.io.PrintWriter;

/**
 * Headless decompilation script: exports all functions' C pseudocode to a file.
 * Usage with analyzeHeadless:
 *   analyzeHeadless <project> <binary> -scriptPath /scripts -postScript DecompileAll.java "/samples/akira_decompiled.c"
 */
public class DecompileAll extends GhidraScript {

	@Override
	protected void run() throws Exception {
		String out = getScriptArgs()[0];

		DecompInterface di = new DecompInterface();
		di.openProgram(currentProgram);

		try (PrintWriter w = new PrintWriter(out)) {
			for (Function f : currentProgram.getFunctionManager().getFunctions(true)) {
				DecompileResults r = di.decompileFunction(f, 120, monitor);
				if (r.decompileCompleted()) {
					w.println(r.getDecompiledFunction().getC() + "\n");
				}
			}
		}

		print("Finished.");
	}
}

